// A driver's stray upload can be filed as another load's pickup photo: the camera JPEG is taken back out of the PDF
// the driver app built. Run: npm test
const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');

process.env.DATA_DIR = fs.mkdtempSync(path.join(os.tmpdir(), 'hp-pickup-'));
const { PDFDocument } = require('pdf-lib');
const { jpegsInPdf } = require('../pods');

// 2x2 baseline JPEG
const JPG = Buffer.from('', 'base64');

test('the camera photo comes back out of a driver PDF unchanged, one per page', async () => {
  const doc = await PDFDocument.create();
  for (let i = 0; i < 2; i++) { const img = await doc.embedJpg(new Uint8Array(JPG)); const p = doc.addPage([612, 792]); p.drawImage(img, { x: 0, y: 0, width: 612, height: 792 }); }
  const out = await jpegsInPdf(Buffer.from(await doc.save()));
  assert.strictEqual(out.length, 2);
  assert.ok(out.every(b => b.equals(JPG)));
});

test('a PDF with no photo in it gives none', async () => {
  const doc = await PDFDocument.create(); doc.addPage();
  assert.deepStrictEqual(await jpegsInPdf(Buffer.from(await doc.save())), []);
});
